mapper.select:
SELECT user_id, user_name, user_email, user_number
FROM users
WHERE user_token = #{user_token}

SELECT es.score_id, es.student_id, u.user_name as student_name, u.user_number as student_number, es.exam_name, es.exam_date, es.score, es.comment FROM exam_scores es JOIN users u ON es.student_id = u.user_id WHERE es.class_id = #{class_id} AND es.subject_id = #{subject_id}
AND es.exam_name = #{exam_name}
ORDER BY es.exam_date DESC
